const I={};
let CURM; // พารามิเตอร์ของหน้าปัจจุบัน (ใช้รีเฟรชหน้าหมวดหมู่)
let P=[]; // [id,name,price,stock,sold,image,desc,options,option_stock,category_id] — โหลดจากตาราง products ใน Supabase PXPSHOP
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let AGP=null; // ราคาตัวแทน {productId:{optionIdx:price}} จาก my_agent_info (null = ไม่ใช่ตัวแทน → ใช้ราคาปกติ)
const agPx=r=>{const o=Array.isArray(r.options)?r.options:[],m=AGP&&AGP[r.id];if(!m)return[Number(r.price)||0,o];
if(o.length){const n=o.map((x,i)=>m[i]!=null&&isFinite(+m[i])?{...x,p:+m[i]}:x);return[Math.min(...n.map(x=>+x.p||0)),n]}
return[m['-1']!=null&&isFinite(+m['-1'])?+m['-1']:(Number(r.price)||0),o]};
let FSP=null,FST=null; // ລາຄາ Flash Sale {productId:{optionIdx:price}} (null = ບໍ່ມີໂປຣ) — ການຄິດເງິນຈິງເຮັດຝັ່ງເຊີບເວີ (purchase_product)
const fxPx=r=>{const a=agPx(r),f=FSP&&FSP[r.id];if(!f)return a;const o=a[1];
if(o.length){const n=o.map((x,i)=>f[i]!=null&&isFinite(+f[i])?{...x,p:Math.min(+x.p||0,+f[i])}:x);return[Math.min(...n.map(x=>+x.p||0)),n]}
return f['-1']!=null&&isFinite(+f['-1'])?[Math.min(a[0],+f['-1']),o]:a};
const pm=r=>{const a=fxPx(r);return [r.id,r.name,a[0],r.stock|0,r.sold|0,r.image_url||'',r.description||'',a[1],r.option_stock||{},r.category_id||null,r.sales_closed===true,r.update_mode===true]};
const pout=p=>p[7].length?p[7].every((_,i)=>((p[8]||{})[i]|0)<1):p[3]<1; // สินค้าหมดจริง (รองรับแบบแพ็กเกจ)
const pst=p=>p[11]?'upd':p[10]?'off':pout(p)?'out':'ok'; // สถานะ: upd=กำลังอัปเดต off=ปิดขาย out=สินค้าหมด ok=ขายปกติ
const PSL={upd:'กำลังอัปเดต',off:'ปิดขาย',out:'สินค้าหมด'};
const PS1={upd:'UPDATE',off:'CLOSED',out:'SOLD'},PS2={upd:'กำลังอัปเดต',off:'ปิดขาย',out:'OUT'},PSB={upd:'กำลังอัปเดต',off:'ปิดขาย',out:'SOLD OUT'};
const NOI='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M5.6 5.6l12.8 12.8"/></svg>';
const ptag=p=>{const s=pst(p);return s==='ok'?'':`<span class="pc-tag ${s}"><b>${PS1[s]}</b><i>${PS2[s]}</i></span>`};
async function loadCats(){if(!sb)return;try{const r=await sb.from('categories').select('id,name,image_url').eq('is_active',true).order('sort_order',{ascending:true}).order('created_at',{ascending:true});if(!r.error)cats=(r.data||[]).map(c=>[c.id,c.name,'','',c.image_url||''])}catch(_){}}
async function loadProds(){if(!sb)return;await loadCats();try{const{data}=await sb.from('products').select('*').eq('is_active',true).order('created_at',{ascending:false});try{const fr=await sb.from('flash_sales').select('product_id,option_idx,price,ends_at').gt('ends_at',new Date().toISOString());if(!fr.error){const m={};let nx=0;(fr.data||[]).forEach(x=>{(m[x.product_id]=m[x.product_id]||{})[x.option_idx]=+x.price;const t=new Date(x.ends_at).getTime();if(!nx||t<nx)nx=t});FSP=Object.keys(m).length?m:null;clearTimeout(FST);if(nx)FST=setTimeout(()=>loadProds(),Math.min(Math.max(nx-Date.now(),0)+1500,2000000000))}}catch(_){}P=(data||[]).map(pm)}catch(_){}try{const r=await sb.rpc('recent_orders',{p_limit:10});if(!r.error)ROR=r.data||[]}catch(_){}try{const r=await sb.rpc('shop_stats');if(!r.error&&r.data)ST={u:+r.data.users||0,s:+r.data.stock||0,o:+r.data.orders||0}}catch(_){}if(CUR==='home'||CUR==='list'||CUR==='cat')show(CUR,CURM)}
const optLbl=o=>o.d&&o.h?{n:o.d,u:'วัน '+o.h+' ชม.'}:o.d?{n:o.d,u:'วัน'}:{n:o.h,u:'ชม.'};
const optsOf=p=>p[7].length?p[7].map(o=>({...o,...optLbl(o)})):[{n:1,u:'ชิ้น',p:p[2],_:1}];
const bsl=()=>P.filter(x=>x[4]>0).sort((a,b)=>b[4]-a[4]).slice(0,2);
const PH='<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="9" cy="10" r="1.8"/><path d="M21 16l-5-5-8 8"/></svg>';
const CHK='<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 8h14l1 12H4z"/><path d="M9 8V7a3 3 0 016 0v1"/><path d="M9 14l2 2 4-4"/></svg>';
const CART='<svg viewBox="0 0 24 24" width="15" height="15" style="vertical-align:-3px;margin-left:3px" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h3l2.5 12h11L21 7H6"/><circle cx="9" cy="20" r="1.6"/><circle cx="17" cy="20" r="1.6"/></svg>';
const box='<svg viewBox="0 0 24 24" width="14" height="14" style="vertical-align:-2px;margin-right:4px" fill="#9a918b"><path d="M3 5h14v4H3zM4 10h12v8H4z"/><circle cx="18" cy="18" r="4" fill="#7a7370"/></svg>';
const IAR=(()=>{try{return JSON.parse(localStorage.getItem('px_iar')||'{}')||{}}catch(_){return{}}})();
const iarSt=src=>IAR[src]&&(!window.sxFit||window.sxFit('prod'))?` style="aspect-ratio:${IAR[src]}"`:'';
const HOTB='<svg class="hotb" viewBox="56 83 1329 750" aria-label="HOT" role="img"><use href="#hotbg"/></svg>';
const isHot=p=>bsl().some(x=>x[0]===p[0]);
const card=p=>`<div class="card pc${pst(p)!=='ok'?' pc-'+pst(p):''}"><div class="pi"${iarSt(p[5])}><div class="ph">${p[5]?`<img src="${esc(p[5])}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover">`:PH}</div>${ptag(p)}</div>${isHot(p)?HOTB:''}<h3>${esc(p[1])}</h3><div class="pr">${p[7].length?'เริ่ม ':''}${tpf(p[2])} กีบ</div><button class="buy${pst(p)!=='ok'?' buy-'+pst(p):''}" ${pst(p)==='out'?'disabled aria-disabled="true"':`data-v="order" data-m="${p[0]}"`}>${pst(p)==='ok'?'สั่งซื้อ '+CART:NOI+PSB[pst(p)]}</button><div class="sk"><span>${CHK}ขายแล้ว <b>${p[4]}</b></span><span>${box}เหลือ <b>${p[3]}</b></span></div>${p[4]+p[3]>0?`<div class="bar"><i style="width:${Math.round(p[4]/(p[4]+p[3])*100)}%"></i></div>`:''}</div>`;
let cats=[]; // [id,name,'','',image_url] — โหลดจากตาราง categories ใน Supabase PXPSHOP (จัดการได้ที่ ห้องแอดมิน > จัดการหมวดหมู่)
const homeSecs=()=>{const row=ps=>ps.length?`<div class="hs-row">${ps.map(card).join('')}</div>`:'';let h=cats.map(c=>{const ps=P.filter(p=>p[9]===c[0]);return `<section class="cs"><div class="cs-h"><i class="cs-bar"></i><h3>${esc(c[1])}</h3><a href="#" class="cs-more" data-v="cat" data-m="${c[0]}">${ps.length} รายการ ›</a></div>${c[4]?`<a href="#" class="cs-bn" data-v="cat" data-m="${c[0]}" aria-label="${esc(c[1])}"><img src="${esc(c[4])}" alt="" loading="lazy"></a>`:''}${row(ps)}</section>`}).join('');const o=P.filter(p=>!cats.some(c=>c[0]===p[9]));if(o.length)h+=`<section class="cs"><div class="cs-h"><i class="cs-bar"></i><h3>สินค้าอื่น ๆ</h3><span class="cs-more">${o.length} รายการ</span></div>${row(o)}</section>`;return h||hsEmpty};
const cat=(c,i)=>{const n=P.filter(p=>p[9]===c[0]).length;return `<a href="#" class="card cat" data-v="cat" data-m="${c[0]}" data-n="${esc(c[1]).toLowerCase()}" data-i="${i}"><div class="ph"${window.sxCatSt?window.sxCatSt(c[4]):''}>${c[4]?`<img src="${esc(c[4])}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">`:PH}</div><div class="ct"><h3>${esc(c[1])}</h3><span class="cn">${n?n+' สินค้า':''}</span><span class="pr2">${c[3]}</span></div></a>`};
let ST={u:0,s:0,o:0}; // สถิติหน้าหลักจริง: ผู้ใช้งาน / สต็อก / ยอดขาย (ฟังก์ชัน shop_stats)
const SXI={u:'<circle cx="12" cy="8" r="3.6"/><path d="M4.8 20c0-4 3.2-6.4 7.2-6.4s7.2 2.4 7.2 6.4"/>',s:'<circle cx="12" cy="12" r="8.5"/><path d="M8.2 12.4l2.8 2.8 5-5.6"/>',o:'<path d="M3.5 17l5.5-5.5 3.5 3.5 8-8"/><path d="M15 7h5.5v5.5"/>'};
const sxCard=(k,label,val,unit,w)=>`<div class="sx${w?' w':''}"><svg class="sx-wm" viewBox="0 0 24 24" aria-hidden="true">${SXI[k]}</svg><span class="sx-ic"><svg viewBox="0 0 24 24" aria-hidden="true">${SXI[k]}</svg></span><span class="sx-tx"><small class="sx-lb">${label}</small><b class="sx-nm">${tpf(val)}<i>${unit}</i></b></span></div>`;
