'<path d="M3 8h7l6 26h28l5-19H13"/><path d="M16 18h34M18 26h30M24 15l2 19M33 15l1 19M42 15l-1 19"/><circle cx="22" cy="44" r="4"/><circle cx="42" cy="44" r="4"/>',
