const isAdm=()=>!!(USER&&PROF&&PROF.role==='admin'); // ADMIN
// ADMIN: การ์ดเมนูห้องแอดมิน ใช้ดีไซน์เดียวกับปุ่มการ์ดหน้าหลัก (.bt) [บรรทัดบนเล็ก, ชื่อใหญ่, ขนาดตัวอักษร, ไอคอน 60x60] — หน้าปลายทางยังเป็นหน้าเปล่า รอทำทีละหน้า
