if(b=t.closest('[data-ttr]')){ttOpen(b.dataset.ttr,false);return}
if(t.closest('.tt-cx')){tpClose();return}
if(b=t.closest('[data-rs]')){b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));const a=$('.tt-ta');if(a)a.value=b.dataset.rs;return}
